import sys
from pathlib import Path
p = Path(sys.argv[1])
lines = p.read_bytes().decode("utf-8").split("\n")
r55 = ("| Run the watcher | `Monitor`, with no timeout, running the command the `watch: not running`, `still running` or `no event for <name> in 2 h` line prints, as is (it ends with `--stream`); each notification (event lines closed by `... still watching`) starts a turn of the idle Chief of Staff session, and so does the monitor's end (its last line). Auto mode drops every `Monitor` allow rule (\"What not to add\"): the start is the classifier's call | unproved; trial: a batch with two merges and one watcher, the Chief of Staff's transcript showing two notifications, two forge checks and two `order merged`, no watcher started and no user message between. A `config@1` line the board writes (a limit saved on its Configuration page) wakes the watcher like a merge: unproved; trial: save `batch.slots` on the board with a watcher running, see the `config changed on the board` line in its notification. The trial also covers a board move with no batch running and the session's turn that follows. The `no event for <name> in 2 h` line, like the `still running` line, names the restart command: run as is, nothing told to the user. The watcher may start the board as a detached process (`serve --seat <id> --stop-idle`), no background task of the session: unproved that it outlives the watcher and that the host does not see it as one; trial: with no board running, start the watcher, see its `started the board (PID <n>)` line; stop the watcher's task, then ask `GET /api/board` with the key: it answers, and the host lists no board task; end the session, ask again: it answers (until the seat leaves or 30 minutes with no client); the trial, when run, records its date and result in this row. |")
r56 = ("| The watcher when the session ends | whether the host ends a background command when the session ends | unproved; trial as for the board's row. Until then an orphaned watcher ends once the project's seat is another session's or, with no batch in flight, 2 h after its last event or its batch's end (the CLI); while one is in flight it runs until the seat moves (accepted, watcher-limit-Q1); the board it observed stops 30 minutes after it ends; the trial, when run, records its date and result in this row |")
i = next(n for n, x in enumerate(lines) if x.startswith("| Run the watcher |"))
assert lines[i + 1].startswith("| The watcher when the session ends |")
eol = "\r" if lines[i].endswith("\r") else ""
lines[i], lines[i + 1] = r55 + eol, r56 + eol
p.write_bytes("\n".join(lines).encode("utf-8"))
